mapper.select:
select se.id, se.user_id as userId, se.identity_id as identityId, se.event_type as eventType, se.event_result as eventResult, se.risk_level as riskLevel, se.ip, se.user_agent as userAgent, se.device_id as deviceId, se.created_at as createdAt, u.account_name as accountName, ai.provider from cm_security_events se left join cm_users u on u.id = se.user_id left join cm_auth_identities ai on ai.id = se.identity_id where 1 = 1
and se.user_id = #{userId}
and se.event_type = #{eventType}
and se.event_result = #{eventResult}
and se.created_at >= #{dateFrom}
and se.created_at <= #{dateTo}
and ( se.user_id = #{keyword} or u.account_name like concat('%', #{keyword}, '%') or se.ip like concat('%', #{keyword}, '%') )
order by se.created_at desc, se.id desc
